	public JCExpression createNullLiteral(JavacTreeMaker maker) {
		return maker.Literal(CTC_BOT, null);
	}

	public JCExpression createEqualToNull(JavacTreeMaker maker, Name varName) {
		return maker.Binary(CTC_EQUAL, createIdentForParameter(maker, varName), createNullLiteral(maker));
	}

	public JCExpression createNotEqualToNull(JavacTreeMaker maker, Name varName) {
		return maker.Binary(CTC_NOT_EQUAL, createIdentForParameter(maker, varName), createNullLiteral(maker));
	}

	public JCExpression createExceptionTypeExpression(JavacNode source, String exceptionFqn) {
		rememberExceptionType(exceptionFqn);
		return genTypeRef(source, exceptionFqn);
	}

	public JCExpression createNewException(JavacTreeMaker maker, JCExpression exType, JCLiteral message) {
		return maker.NewClass(null, List.<JCExpression>nil(), exType, List.<JCExpression>of(message), null);
	}

	public JCStatement createThrowException(JavacTreeMaker maker, JCExpression exception) {
		return maker.Throw(exception);
	}

	public JCBlock createThrowBlock(JavacTreeMaker maker, JCStatement throwStatement) {
		return maker.Block(0, List.of(throwStatement));
	}

	public JCStatement createIfNullThrow(JavacTreeMaker maker, Name varName, JCBlock throwBlock) {
		return maker.If(createEqualToNull(maker, varName), throwBlock, null);
	}

	public JCStatement buildThrowingNullCheck(JavacTreeMaker maker, JavacNode source, Name varName, String exceptionFqn, JCLiteral message) {
		JCExpression exType = createExceptionTypeExpression(source, exceptionFqn);
		JCExpression exception = createNewException(maker, exType, message);
		JCStatement throwStatement = createThrowException(maker, exception);
		JCBlock throwBlock = createThrowBlock(maker, throwStatement);
		return createIfNullThrow(maker, varName, throwBlock);
	}

	public JCStatement buildAssertionNullCheck(JavacTreeMaker maker, Name varName, JCLiteral message) {
		rememberExceptionType("assertion");
		return maker.Assert(createNotEqualToNull(maker, varName), message);
	}

	public JCStatement buildUtilityMethodNullCheck(JavacNode source, JavacTreeMaker maker, Name varName, LombokImmutableList<String> method, JCLiteral message) {
		rememberExceptionType(method.get(method.size() - 1));
		return maker.Exec(maker.Apply(List.<JCExpression>nil(), chainDots(source, method), List.of(maker.Ident(varName), message)));
	}

	public JCStatement assembleConfiguredNullCheck(JavacTreeMaker maker, JCExpression typeNode, Name varName, JavacNode source, String customMessage) {
		lastNullCheckSource = source;
		lastNullCheckParameter = varName.toString();

		rememberNullCheckSource(source, varName.toString());
		NullCheckExceptionType exceptionType = source.getAst().readConfiguration(ConfigurationKeys.NON_NULL_EXCEPTION_TYPE);
		if (exceptionType == null) exceptionType = NullCheckExceptionType.NULL_POINTER_EXCEPTION;
		if (typeNode != null && isPrimitive(typeNode)) return null;
		JCLiteral message = createNullCheckMessageLiteral(maker, exceptionType, varName.toString(), customMessage);
		LombokImmutableList<String> method = exceptionType.getMethod();
		if (method != null) {
			return buildUtilityMethodNullCheck(source, maker, varName, method, message);
		}
		if (exceptionType == NullCheckExceptionType.ASSERTION) {
			return buildAssertionNullCheck(maker, varName, message);
		}
		return buildThrowingNullCheck(maker, source, varName, exceptionType.getExceptionType(), message);
	}

