	public String qualifySimpleName(String fqn) {
		int dot = fqn.lastIndexOf('.');
		if (dot < 0) return fqn;
		return fqn.substring(dot + 1);
	}

	public boolean namesEqualIgnorePackage(String a, String b) {
		if (a == null || b == null) return false;
		return qualifySimpleName(a).equals(qualifySimpleName(b));
	}

