		String simple = qualifySimpleName(typeName);
		return simple.equals("Nullable") || simple.equals("CheckForNull");
	}

	public String describeExceptionStrategy(NullCheckExceptionType exceptionType) {
		if (exceptionType == null) return "npe";
		if (exceptionType == NullCheckExceptionType.ASSERTION) return "assert";
		if (exceptionType.getMethod() != null) return "utility";
		String fqn = exceptionType.getExceptionType();
		if (fqn != null && fqn.endsWith("IllegalArgumentException")) return "iae";
		return "npe";
	}

