input.command:
docker exec cli-eval-opencode-projectlombok__lombok-3371-485ee7b3 sh -lc 'java -version 2>&1 | head -3; mkdir -p /tmp/nnrec && cat > /tmp/nnrec/NamedByteArray.java <<EOF
import lombok.NonNull;
public record NamedByteArray(@NonNull String name, byte @NonNull[] bytes) {}
EOF
cat > /tmp/nnrec/Test.java <<EOF
public class Test {
  public static void main(String[] a) {
    try { new NamedByteArray("name", null); System.out.println("NO NPE"); }
    catch (NullPointerException e) { System.out.println("NPE: " + e.getMessage()); }
    try { new NamedByteArray(null, new byte[0]); System.out.println("NO NPE name"); }
    catch (NullPointerException e) { System.out.println("NPE name: " + e.getMessage()); }
    try { new NamedByteArray("name", new byte[0]); System.out.println("OK"); }
    catch (Throwable t) { System.out.println("FAIL: " + t); }
  }
}
EOF
javac -cp /testbed/dist/lombok.jar -d /tmp/nnrec /tmp/nnrec/NamedByteArray.java /tmp/nnrec/Test.java && java -cp /tmp/nnrec:/testbed/dist/lombok.jar Test'

